y with purpose.
INSERT INTO workspaces (country,plan_type,city,timezone,gstin,gst_billing_address,business_type,gst_business_name,currency,state,email,business_category,owner_user_id,gst_enabled,gst_state,phone,custom_business_type,name,default_gst_rate,plan_status,id,created_at,updated_at,created_by_id) VALUES ('India','free','vadodaraa','Asia/Kolkata','','','Event Management','','INR','Gujarat','ns51@dipakpatel.site','PHOTOGRAPHY','6aa19818-0e29-0303-7c88-038800000000',false,'','+918155069901','','test',18,'active','6aa2d913-1dba-f883-1d2f-0beb00000000','2026-09-10T16:21:39.013000','2026-09-11T13:08:45.343000','6aa19818-0e29-0303-7c88-038800000000') ON CONFLICT (id) DO NOTHING;
INSERT INTO workspaces (public_profile_slug,tagline,gst_business_name,default_gst_rate,number_format,public_profile_social_links,city,country,custom_business_type,gst_enabled,business_category,currency,email,gstin,plan_status,website,owner_user_id,display_preferences,public_profile_about,event_types,gst_billing_address,timezone,gst_state,phone,fy_start_month,state,logo,business_type,team_member_types,address,public_profile_enabled,name,date_format,plan_type,id,created_at,updated_at,created_by_id) VALUES ('krishna-shah-photography','Capturing the Moments that awe you !','',18,'indian','{"facebook":"https://www.facebook.com/KrishnaShahPhotographyy","website":"https://krishnashah.photography/","instagram":"https://www.instagram.com/KrishnaShah.Photography","youtube":"https://www.youtube.com/@krishnashahphotography"}'::jsonb,'Vadodara','India','',false,'PHOTOGRAPHY','INR','workatksp@gmail.com','','active','https://krishnashah.photography','6aa20f28-3c80-81b6-ff82-05cf00000000','{"showProgressIndicators":true,"showMemberTypeColors":true,"showStatusDots":true,"showTeam":true,"showServices":true,"showAddressOnCards":false,"showServicesOnCards":false,"groupUpcoming":true,"showMenubarLabels":true,"pastelPalette":["#F4A6B8","#A8C8E8","#B8D8A8","#F4D4A8","#C8A8D8"],"pastelThemeIndex":0,"showLogo":true,"defaultTerms":"<p>Typically,&nbsp;you’ll&nbsp;sign&nbsp;a&nbsp;contract&nbsp;before&nbsp;your&nbsp;event.&nbsp;However,&nbsp;booking&nbsp;implies&nbsp;you’ve&nbsp;read,&nbsp;understood,&nbsp;and&nbsp;agreed&nbsp;to&nbsp;the&nbsp;terms&nbsp;below.&nbsp;These&nbsp;terms&nbsp;represent&nbsp;the&nbsp;total&nbsp;agreement&nbsp;between&nbsp;us,&nbsp;and&nbsp;any&nbsp;changes&nbsp;must&nbsp;be&nbsp;agreed&nbsp;upon&nbsp;in&nbsp;writing&nbsp;by&nbsp;both&nbsp;parties.</p><p></p><p><strong>Booking&nbsp;&amp;&nbsp;Cancellation&nbsp;:</strong>&nbsp;The&nbsp;Booking&nbsp;Fee,&nbsp;which&nbsp;is&nbsp;half&nbsp;of&nbsp;the&nbsp;total&nbsp;cost&nbsp;(50%),&nbsp;confirms&nbsp;your&nbsp;date&nbsp;with&nbsp;the&nbsp;photographer&nbsp;and&nbsp;is&nbsp;not&nbsp;refundable&nbsp;if&nbsp;you&nbsp;cancel.&nbsp;If&nbsp;you&nbsp;cancel&nbsp;within&nbsp;four&nbsp;weeks&nbsp;(or&nbsp;1&nbsp;month)&nbsp;of&nbsp;the&nbsp;event,&nbsp;you’ll&nbsp;need&nbsp;to&nbsp;pay&nbsp;the&nbsp;full&nbsp;amount.&nbsp;Any&nbsp;cancellations&nbsp;must&nbsp;be&nbsp;in&nbsp;writing.&nbsp;If&nbsp;you&nbsp;postpone&nbsp;your&nbsp;event,&nbsp;you&nbsp;can&nbsp;keep&nbsp;the&nbsp;fee&nbsp;as&nbsp;long&nbsp;as&nbsp;the&nbsp;photographer&nbsp;can&nbsp;reschedule&nbsp;for&nbsp;the&nbsp;new&nbsp;date/time.&nbsp;The&nbsp;fee&nbsp;for&nbsp;postponed&nbsp;event&nbsp;is&nbsp;subject&nbsp;to&nbsp;change.</p><p></p><p><strong>Payment&nbsp;Terms&nbsp;:</strong></p><p></p><p>50%&nbsp;advanced&nbsp;payment&nbsp;|&nbsp;30%&nbsp;payment&nbsp;on&nbsp;day&nbsp;of&nbsp;event&nbsp;|&nbsp;20%&nbsp;payment&nbsp;on&nbsp;day&nbsp;of&nbsp;delivery</p><p></p><p>Please&nbsp;note&nbsp;that&nbsp;no&nbsp;USB,&nbsp;HDD,&nbsp;frame,&nbsp;album,&nbsp;or&nbsp;any&nbsp;optional&nbsp;extras&nbsp;will&nbsp;be&nbsp;delivered&nbsp;or&nbsp;included&nbsp;as&nbsp;part&nbsp;of&nbsp;your&nbsp;package&nbsp;unless&nbsp;explicitly&nbsp;stated&nbsp;in&nbsp;the&nbsp;quotation.&nbsp;These&nbsp;items&nbsp;will&nbsp;only&nbsp;be&nbsp;provided&nbsp;once&nbsp;all&nbsp;payments&nbsp;due&nbsp;have&nbsp;been&nbsp;paid&nbsp;in&nbsp;full.&nbsp;Payments&nbsp;can&nbsp;be&nbsp;made&nbsp;via&nbsp;cheque&nbsp;or&nbsp;bank&nbsp;transfer.</p><p></p><p><strong>Timings&nbsp;:&nbsp;</strong>Payment&nbsp;for&nbsp;any&nbsp;additional&nbsp;attendance&nbsp;hours&nbsp;(whether&nbsp;partial&nbsp;or&nbsp;full),&nbsp;which&nbsp;may&nbsp;have&nbsp;been&nbsp;agreed&nbsp;upon&nbsp;but&nbsp;were&nbsp;not&nbsp;accurately&nbsp;known&nbsp;at&nbsp;the&nbsp;time&nbsp;of&nbsp;signing&nbsp;the&nbsp;contract,&nbsp;must&nbsp;be&nbsp;settled&nbsp;at&nbsp;the&nbsp;post-event&nbsp;delivery&nbsp;meeting.&nbsp;The&nbsp;photographer’s&nbsp;coverage&nbsp;will&nbsp;begin&nbsp;at&nbsp;the&nbsp;scheduled&nbsp;start&nbsp;time&nbsp;and&nbsp;end&nbsp;at&nbsp;the&nbsp;agreed-upon&nbsp;finish&nbsp;time.&nbsp;If&nbsp;the&nbsp;event&nbsp;is&nbsp;delayed&nbsp;or&nbsp;if&nbsp;additional&nbsp;hours&nbsp;are&nbsp;required,&nbsp;overtime&nbsp;charges&nbsp;will&nbsp;apply.&nbsp;Any&nbsp;changes&nbsp;to&nbsp;the&nbsp;event’s&nbsp;timing&nbsp;or&nbsp;location&nbsp;should&nbsp;be&nbsp;communicated&nbsp;promptly&nbsp;to&nbsp;avoid&nbsp;adjustments&nbsp;to&nbsp;the&nbsp;schedule&nbsp;or&nbsp;additional&nbsp;fees.</p><p></p><p><strong>Cooperation&nbsp;:</strong>&nbsp;We&nbsp;agree&nbsp;to&nbsp;work&nbsp;together&nbsp;happily&nbsp;and&nbsp;talk&nbsp;openly&nbsp;to&nbsp;get&nbsp;the&nbsp;best&nbsp;pictures&nbsp;possible.&nbsp;It’s&nbsp;a&nbsp;good&nbsp;idea&nbsp;to&nbsp;have&nbsp;someone&nbsp;like&nbsp;the&nbsp;best&nbsp;man&nbsp;help&nbsp;the&nbsp;photographer&nbsp;by&nbsp;pointing&nbsp;out&nbsp;important&nbsp;people&nbsp;and&nbsp;organizing&nbsp;family&nbsp;pictures.&nbsp;Make&nbsp;sure&nbsp;to&nbsp;tell&nbsp;the&nbsp;photographer&nbsp;about&nbsp;important&nbsp;moments&nbsp;during&nbsp;the&nbsp;event,&nbsp;like&nbsp;throwing&nbsp;flowers&nbsp;or&nbsp;cutting&nbsp;the&nbsp;cake,&nbsp;so&nbsp;that&nbsp;we&nbsp;can&nbsp;be&nbsp;prepared.&nbsp;Please&nbsp;note&nbsp;that&nbsp;not&nbsp;all&nbsp;guests&nbsp;at&nbsp;events&nbsp;or&nbsp;weddings&nbsp;like&nbsp;having&nbsp;their&nbsp;photo&nbsp;taken.&nbsp;In&nbsp;such&nbsp;cases&nbsp;the&nbsp;Photographer&nbsp;will&nbsp;use&nbsp;his&nbsp;discretion&nbsp;but&nbsp;cannot&nbsp;be&nbsp;held&nbsp;responsible&nbsp;for&nbsp;a&nbsp;lack&nbsp;of&nbsp;photos&nbsp;of&nbsp;these&nbsp;people.</p><p></p><p><strong>The&nbsp;Schedule&nbsp;:&nbsp;</strong>We&nbsp;plan&nbsp;our&nbsp;schedule,&nbsp;how&nbsp;we&nbsp;work,&nbsp;and&nbsp;our&nbsp;experience&nbsp;to&nbsp;make&nbsp;sure&nbsp;we&nbsp;capture&nbsp;wonderful&nbsp;photos/videos&nbsp;that&nbsp;everyone&nbsp;enjoys.&nbsp;Both&nbsp;of&nbsp;us&nbsp;need&nbsp;to&nbsp;be&nbsp;on&nbsp;time&nbsp;and&nbsp;work&nbsp;together&nbsp;with&nbsp;a&nbsp;positive&nbsp;attitude&nbsp;to&nbsp;get&nbsp;the&nbsp;best&nbsp;outcome.&nbsp;If&nbsp;things&nbsp;run&nbsp;late,&nbsp;like&nbsp;if&nbsp;someone&nbsp;is&nbsp;very&nbsp;late,&nbsp;we&nbsp;might&nbsp;not&nbsp;be&nbsp;able&nbsp;to&nbsp;take&nbsp;all&nbsp;the&nbsp;usual&nbsp;photos/videos.&nbsp;But&nbsp;we&nbsp;will&nbsp;try&nbsp;our&nbsp;best&nbsp;to&nbsp;make&nbsp;up&nbsp;for&nbsp;it&nbsp;and&nbsp;still&nbsp;get&nbsp;great&nbsp;outcome.</p><p></p><p><strong>Confirmation&nbsp;:</strong>&nbsp;Client&nbsp;will&nbsp;receive&nbsp;a&nbsp;confirmation&nbsp;mail&nbsp;or&nbsp;message&nbsp;and&nbsp;a&nbsp;receipt&nbsp;on&nbsp;receiving&nbsp;the&nbsp;Booking&nbsp;amount.&nbsp;This&nbsp;message&nbsp;confirms&nbsp;the&nbsp;Booking&nbsp;with&nbsp;‘Krishna&nbsp;Shah&nbsp;Photography‘.&nbsp;Any&nbsp;verbal&nbsp;communication&nbsp;DOES&nbsp;NOT&nbsp;guarantee&nbsp;a&nbsp;booking&nbsp;if&nbsp;the&nbsp;advance&nbsp;amount&nbsp;is&nbsp;not&nbsp;paid.</p><p></p><p><strong>Delivery&nbsp;:</strong></p><p>Pre-wedding&nbsp;:&nbsp;3-5&nbsp;Weeks&nbsp;after&nbsp;the&nbsp;service&nbsp;date&nbsp;in&nbsp;off-season&nbsp;or&nbsp;up&nbsp;to&nbsp;5&nbsp;Weeks&nbsp;after&nbsp;the&nbsp;service&nbsp;date&nbsp;in&nbsp;peak&nbsp;season.</p><p>Wedding&nbsp;:&nbsp;Subject&nbsp;to&nbsp;duration&nbsp;of&nbsp;photography&nbsp;services.&nbsp;The&nbsp;more&nbsp;drawn&nbsp;out&nbsp;of&nbsp;photography&nbsp;services&nbsp;implies&nbsp;we&nbsp;will&nbsp;produce&nbsp;more&nbsp;photographs&nbsp;and&nbsp;it&nbsp;will&nbsp;require&nbsp;longer&nbsp;time&nbsp;for&nbsp;post&nbsp;processing.&nbsp;For&nbsp;the&nbsp;most&nbsp;part&nbsp;we&nbsp;may&nbsp;convey&nbsp;the&nbsp;outcome&nbsp;in&nbsp;5-7&nbsp;Weeks&nbsp;after&nbsp;the&nbsp;service&nbsp;date&nbsp;in&nbsp;off-season&nbsp;or&nbsp;maximum&nbsp;7&nbsp;Weeks&nbsp;in&nbsp;peak&nbsp;season.</p><p>Other&nbsp;Events&nbsp;:&nbsp;Subject&nbsp;to&nbsp;duration&nbsp;of&nbsp;photography&nbsp;services.&nbsp;For&nbsp;the&nbsp;most&nbsp;part&nbsp;we&nbsp;may&nbsp;convey&nbsp;the&nbsp;outcome&nbsp;in&nbsp;1&nbsp;Week&nbsp;after&nbsp;the&nbsp;service&nbsp;date&nbsp;in&nbsp;off-season&nbsp;or&nbsp;maximum&nbsp;3&nbsp;Weeks&nbsp;in&nbsp;peak&nbsp;season.</p><p></p><p><strong>Images&nbsp;&amp;&nbsp;Retouching&nbsp;:</strong>&nbsp;All&nbsp;images&nbsp;are&nbsp;provided&nbsp;in&nbsp;high&nbsp;quality&nbsp;to&nbsp;clients,&nbsp;with&nbsp;sizes&nbsp;considered&nbsp;standard.&nbsp;‘Krishna&nbsp;Shah&nbsp;Photography‘&nbsp;will&nbsp;do&nbsp;basic&nbsp;retouching&nbsp;to&nbsp;ensure&nbsp;the&nbsp;photos&nbsp;meet&nbsp;a&nbsp;certain&nbsp;quality&nbsp;standard.</p><p></p><p><strong>AI&nbsp;Gallery&nbsp;&amp;&nbsp;Instant&nbsp;Sharing&nbsp;:</strong>&nbsp;If&nbsp;your&nbsp;package&nbsp;includes&nbsp;an&nbsp;AI&nbsp;Gallery&nbsp;(powered&nbsp;by&nbsp;Samaro&nbsp;AI),&nbsp;photos&nbsp;will&nbsp;be&nbsp;available&nbsp;for&nbsp;viewing&nbsp;and&nbsp;download&nbsp;via&nbsp;facial&nbsp;recognition&nbsp;for&nbsp;a&nbsp;period&nbsp;of&nbsp;thirty&nbsp;(30)&nbsp;days&nbsp;from&nbsp;the&nbsp;date&nbsp;the&nbsp;link&nbsp;is&nbsp;shared.&nbsp;It&nbsp;is&nbsp;the&nbsp;client’s&nbsp;and&nbsp;guests’&nbsp;responsibility&nbsp;to&nbsp;download&nbsp;their&nbsp;desired&nbsp;images&nbsp;within&nbsp;this&nbsp;timeframe.&nbsp;After&nbsp;30&nbsp;days,&nbsp;the&nbsp;gallery&nbsp;will&nbsp;be&nbsp;deactivated&nbsp;to&nbsp;accommodate&nbsp;new&nbsp;event&nbsp;hosting.&nbsp;Please&nbsp;note&nbsp;that&nbsp;the&nbsp;AI&nbsp;Gallery&nbsp;is&nbsp;intended&nbsp;for&nbsp;quick&nbsp;sharing&nbsp;and&nbsp;personal&nbsp;downloads&nbsp;only.</p><p></p><p><strong>Album&nbsp;:</strong>&nbsp;If&nbsp;your&nbsp;package&nbsp;includes&nbsp;an&nbsp;album,&nbsp;photo&nbsp;selection&nbsp;must&nbsp;be&nbsp;completed&nbsp;within&nbsp;three&nbsp;(3)&nbsp;months&nbsp;upon&nbsp;receipt&nbsp;of&nbsp;the&nbsp;raw&nbsp;images.&nbsp;Failure&nbsp;to&nbsp;do&nbsp;so&nbsp;will&nbsp;result&nbsp;in&nbsp;processing&nbsp;of&nbsp;the&nbsp;remaining&nbsp;payment&nbsp;for&nbsp;the&nbsp;services&nbsp;provided,&nbsp;irrespective&nbsp;of&nbsp;whether&nbsp;album&nbsp;photos&nbsp;have&nbsp;been&nbsp;chosen.&nbsp;Prior&nbsp;to&nbsp;printing,&nbsp;a&nbsp;preview&nbsp;PDF&nbsp;will&nbsp;be&nbsp;provided&nbsp;for&nbsp;your&nbsp;approval.&nbsp;Please&nbsp;be&nbsp;advised&nbsp;that&nbsp;no&nbsp;alterations&nbsp;can&nbsp;be&nbsp;made&nbsp;once&nbsp;the&nbsp;preview&nbsp;PDF&nbsp;is&nbsp;finalized&nbsp;and/or&nbsp;printed.</p><p></p><p><strong>Video&nbsp;:</strong>&nbsp;If&nbsp;your&nbsp;package&nbsp;includes&nbsp;traditional/regular&nbsp;videos,&nbsp;we&nbsp;commence&nbsp;editing&nbsp;once&nbsp;we&nbsp;sort&nbsp;out&nbsp;the&nbsp;footages.&nbsp;Audio/songs&nbsp;will&nbsp;be&nbsp;selected&nbsp;based&nbsp;on&nbsp;our&nbsp;expertise&nbsp;and&nbsp;preferences.&nbsp;Editing&nbsp;typically&nbsp;spans&nbsp;3-5&nbsp;weeks.&nbsp;Changes&nbsp;will&nbsp;only&nbsp;be&nbsp;considered&nbsp;in&nbsp;the&nbsp;event&nbsp;of&nbsp;errors&nbsp;or&nbsp;missing&nbsp;footage(s).</p><p></p><p><strong>Cinematic&nbsp;Video&nbsp;:</strong>&nbsp;If&nbsp;your&nbsp;package&nbsp;includes&nbsp;Wedding&nbsp;film/Cinematic&nbsp;video,&nbsp;we&nbsp;kindly&nbsp;request&nbsp;your&nbsp;audio&nbsp;selection.&nbsp;In&nbsp;case&nbsp;you’re&nbsp;unable&nbsp;to&nbsp;provide&nbsp;audio,&nbsp;we&nbsp;will&nbsp;offer&nbsp;suggestions.&nbsp;Editing&nbsp;typically&nbsp;spans&nbsp;4-6&nbsp;weeks.&nbsp;A&nbsp;draft&nbsp;video&nbsp;will&nbsp;be&nbsp;provided&nbsp;before&nbsp;the&nbsp;final&nbsp;files&nbsp;for&nbsp;your&nbsp;review.&nbsp;Once&nbsp;the&nbsp;draft&nbsp;video&nbsp;is&nbsp;finalised,&nbsp;no&nbsp;further&nbsp;changes&nbsp;will&nbsp;be&nbsp;made.</p><p></p><p><strong>Drone&nbsp;(Aerial&nbsp;Photography/Videography)&nbsp;:</strong>&nbsp;If&nbsp;your&nbsp;package&nbsp;includes&nbsp;Drone,&nbsp;please&nbsp;note&nbsp;that&nbsp;drone&nbsp;operations&nbsp;are&nbsp;subject&nbsp;to&nbsp;weather&nbsp;conditions&nbsp;and&nbsp;operational&nbsp;feasibility.&nbsp;We&nbsp;will&nbsp;make&nbsp;reasonable&nbsp;efforts&nbsp;to&nbsp;provide&nbsp;uninterrupted&nbsp;drone&nbsp;services,&nbsp;but&nbsp;adverse&nbsp;weather&nbsp;or&nbsp;safety&nbsp;concerns&nbsp;may&nbsp;require&nbsp;suspension&nbsp;or&nbsp;rescheduling&nbsp;of&nbsp;operations.&nbsp;Please&nbsp;be&nbsp;aware&nbsp;that&nbsp;drone&nbsp;operation&nbsp;may&nbsp;be&nbsp;restricted&nbsp;in&nbsp;areas&nbsp;near&nbsp;airports,&nbsp;military&nbsp;bases,&nbsp;or&nbsp;other&nbsp;sensitive&nbsp;locations.</p><p></p><p><strong>Copyright&nbsp;Law&nbsp;:</strong>&nbsp;The&nbsp;Photographer&nbsp;retains&nbsp;copyright&nbsp;of&nbsp;the&nbsp;photographs.&nbsp;Clients&nbsp;may&nbsp;make&nbsp;copies&nbsp;for&nbsp;personal&nbsp;use&nbsp;and&nbsp;share&nbsp;with&nbsp;friends&nbsp;and&nbsp;family.&nbsp;However,&nbsp;selling,&nbsp;publishing,&nbsp;or&nbsp;commercial&nbsp;use&nbsp;requires&nbsp;prior&nbsp;written&nbsp;consent&nbsp;from&nbsp;the&nbsp;Photographer.</p><p></p><p><strong>Model&nbsp;Release&nbsp;:&nbsp;</strong>The&nbsp;Clients&nbsp;grant&nbsp;the&nbsp;Photographer&nbsp;permission&nbsp;to&nbsp;use&nbsp;their&nbsp;photographs&nbsp;for&nbsp;various&nbsp;purposes,&nbsp;including&nbsp;editorial,&nbsp;advertising,&nbsp;and&nbsp;competitions,&nbsp;with&nbsp;the&nbsp;freedom&nbsp;to&nbsp;alter&nbsp;and&nbsp;copyright&nbsp;the&nbsp;images.&nbsp;The&nbsp;Clients&nbsp;release&nbsp;the&nbsp;Photographer&nbsp;from&nbsp;any&nbsp;liability&nbsp;related&nbsp;to&nbsp;the&nbsp;use&nbsp;of&nbsp;the&nbsp;images.</p><p></p><p><strong>Attendance&nbsp;:</strong>&nbsp;If&nbsp;the&nbsp;assigned&nbsp;Photographer&nbsp;is&nbsp;unable&nbsp;to&nbsp;attend&nbsp;your&nbsp;event&nbsp;due&nbsp;to&nbsp;unforeseen&nbsp;circumstances,&nbsp;we&nbsp;reserve&nbsp;the&nbsp;right&nbsp;to&nbsp;send&nbsp;a&nbsp;replacement&nbsp;photographer&nbsp;to&nbsp;cover&nbsp;the&nbsp;event&nbsp;to&nbsp;the&nbsp;best&nbsp;of&nbsp;their&nbsp;ability.</p><p></p><p><strong>Travel&nbsp;and&nbsp;Subsistence&nbsp;:&nbsp;</strong>For&nbsp;attendance&nbsp;at&nbsp;venues&nbsp;at&nbsp;a&nbsp;distance&nbsp;over&nbsp;20&nbsp;KM&nbsp;radius,&nbsp;travel&nbsp;costs&nbsp;will&nbsp;be&nbsp;charged&nbsp;where&nbsp;necessary.&nbsp;If&nbsp;overnight&nbsp;stay&nbsp;is&nbsp;necessary&nbsp;for&nbsp;event(s)&nbsp;outside&nbsp;Vadodara&nbsp;(Baroda),&nbsp;good&nbsp;hotel&nbsp;and&nbsp;food&nbsp;charges&nbsp;will&nbsp;be&nbsp;billed,&nbsp;unless&nbsp;the&nbsp;client&nbsp;provides&nbsp;accommodation&nbsp;for&nbsp;our&nbsp;team.</p><p></p><p><strong>Complaints&nbsp;:</strong>&nbsp;Client&nbsp;complaints&nbsp;must&nbsp;be&nbsp;submitted&nbsp;in&nbsp;writing&nbsp;mail&nbsp;or&nbsp;message&nbsp;to&nbsp;the&nbsp;Photographer&nbsp;within&nbsp;15&nbsp;days&nbsp;of&nbsp;receiving&nbsp;the&nbsp;soft-copy&nbsp;data.</p><p></p><p><strong>Files&nbsp;Handling/Backup&nbsp;:</strong>&nbsp;Please&nbsp;be&nbsp;noted&nbsp;that&nbsp;we&nbsp;will&nbsp;delete&nbsp;all&nbsp;your&nbsp;event(s)&nbsp;files&nbsp;6&nbsp;months&nbsp;after&nbsp;our&nbsp;service&nbsp;date.</p><p></p><p><strong>Disclaimer&nbsp;:</strong>&nbsp;The&nbsp;photographer&nbsp;reserves&nbsp;the&nbsp;right&nbsp;to&nbsp;change,&nbsp;vary&nbsp;or&nbsp;cancel&nbsp;these&nbsp;Terms&nbsp;and&nbsp;Conditions&nbsp;at&nbsp;any&nbsp;time.&nbsp;If&nbsp;we&nbsp;change&nbsp;our&nbsp;T&amp;Cs,&nbsp;one&nbsp;can&nbsp;visit&nbsp;this&nbsp;page.&nbsp;(https://krishnashah.photography/terms-conditions/)</p><p></p><p>We&nbsp;value&nbsp;our&nbsp;customers&nbsp;and&nbsp;aim&nbsp;to&nbsp;ensure&nbsp;your&nbsp;complete&nbsp;satisfaction&nbsp;with&nbsp;both&nbsp;our&nbsp;service&nbsp;and&nbsp;products.</p><p></p><p>Both&nbsp;parties&nbsp;will&nbsp;agree&nbsp;to&nbsp;these&nbsp;terms&nbsp;upon&nbsp;booking.</p><p></p><p>If&nbsp;you&nbsp;have&nbsp;any&nbsp;questions&nbsp;or&nbsp;would&nbsp;like&nbsp;to&nbsp;discuss&nbsp;our&nbsp;photography&nbsp;terms&nbsp;and&nbsp;conditions,&nbsp;then&nbsp;please&nbsp;contact&nbsp;us.</p>","defaultPaymentMethod":"","defaultPaymentInstructions":"","showLogoOnQuotation":true,"showLogoWatermark":true,"defaultPaymentConditions":"","bank_account_name":"","bank_name":"","bank_account_number":"","bank_ifsc":"","bank_upi_id":"","social_instagram":"https://www.instagram.com/KrishnaShah.Photography","social_youtube":"https://www.youtube.com/@krishnashahphotography","social_website":"https://krishnashah.photography","social_portfolio":"","milestoneTemplates":[{"id":"mt_1789215349150","name":"50-30-20","milestones":[{"name":"Advance","type":"percent","value":50,"due_condition":"On signing"},{"name":"Balance","type":"percent","value":30,"due_condition":"On event day"},{"name":"Final","type":"percent","value":20,"due_condition":"Final delivery"}]}]}'::jsonb,'In 2014 I went from being just a computer engineer to a computer engineer with a D-SLR camera. That gift from my sister and encouragement from other sister helped me see our little world of Baroda in a totally different light.
